#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m20-shelf-db-statefulset pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m20-shelf-db-statefulset
CHECKS="claim-template pod-name claim-bound db-ready backup-succeeded restore-succeeded marker-restored"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m20-shelf-db-statefulset
checks:
  - id: claim-template
    describe: The StatefulSet shelf-db has a volumeClaimTemplate named data
    kubectl:
      - get
      - statefulset
      - shelf-db
      - -n
      - shelf
      - -o
      - jsonpath={.spec.volumeClaimTemplates[*].metadata.name}
    expect:
      equals: data
    hint: "TODO 1: a `volumeClaimTemplates` list in the StatefulSet's spec, with one template named `data`. The field cannot be changed on a StatefulSet that exists, so delete the StatefulSet first if you applied the starting file."
  - id: pod-name
    describe: The database Pod is named shelf-db-0
    kubectl:
      - get
      - pods
      - -n
      - shelf
      - -l
      - app.kubernetes.io/name=shelf-db
      - -o
      - jsonpath={.items[*].metadata.name}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: shelf-db-0
    hint: A StatefulSet names its Pods <name>-<ordinal>. Apply `db-lab/shelf-db.yaml` and run `kubectl get pods --namespace shelf`.
  - id: claim-bound
    describe: The claim data-shelf-db-0 is Bound
    kubectl:
      - get
      - pvc
      - data-shelf-db-0
      - -n
      - shelf
      - -o
      - jsonpath={.status.phase}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: Bound
    hint: The claim is made from the template, named <template>-<StatefulSet>-<ordinal>. `kubectl get pvc --namespace shelf` lists it, and `kubectl describe pvc data-shelf-db-0 --namespace shelf` shows its events.
  - id: db-ready
    describe: The StatefulSet has one ready replica
    kubectl:
      - get
      - statefulset
      - shelf-db
      - -n
      - shelf
      - -o
      - jsonpath={.status.readyReplicas}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "1"
    hint: Run `kubectl describe pod shelf-db-0 --namespace shelf` and `kubectl logs shelf-db-0 --namespace shelf`. The first start takes a few seconds.
  - id: backup-succeeded
    describe: The backup Job shelf-db-backup has succeeded
    kubectl:
      - get
      - job
      - shelf-db-backup
      - -n
      - shelf
      - -o
      - jsonpath={.status.succeeded}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "1"
    hint: "TODO 2: the Job's `args` hold the pg_dump command. Apply `db-lab/backup.yaml`, then run `kubectl logs job/shelf-db-backup --namespace shelf`. A Job's Pod template is fixed, so delete the Job before you apply a corrected one."
  - id: restore-succeeded
    describe: The restore Job shelf-db-restore has succeeded
    kubectl:
      - get
      - job
      - shelf-db-restore
      - -n
      - shelf
      - -o
      - jsonpath={.status.succeeded}
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          equals: "1"
    hint: "TODO 3: createdb, then pg_restore. createdb fails if the database shelf exists, so drop it first with `psql --dbname postgres --command 'drop database shelf with (force)'`. Read `kubectl logs job/shelf-db-restore --namespace shelf`."
  - id: marker-restored
    describe: The marker row from before the backup is in the restored database
    kubectl:
      - exec
      - shelf-db-0
      - -n
      - shelf
      - --
      - psql
      - --username
      - shelf
      - --dbname
      - shelf
      - --tuples-only
      - --no-align
      - --command
      - select count(*) from marker where note = 'before the backup' and written_at < (select (pg_stat_file('base/' || oid || '/PG_VERSION')).modification from pg_database where datname = 'shelf')
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          matches: ^[1-9][0-9]*$
    hint: Write the row before the backup, with the table `marker (note text, written_at timestamptz default now())`. After the restore, `select note from marker` must return it. A row that you write after the restore is newer than the database and does not count.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
